/**
 * requireRegisteredBizContext — requireBizContext, then the AUTHORITATIVE registration of the requested business
 * (I6; independent I5 review I5-R-01). A biz_access grant (or an owner's implicit all-business scope) never substitutes for
 * registration: the business must be classified `registered` by the approved M1 shared target-scoped rule
 * (lib/businessRegistry.js readRegistryTarget — exact identity; a plain/padded twin, a duplicate or a coerced record is
 * ambiguous) in ONE read of tenants/{t}/app/business, after every check of requireBizContext and before the caller touches
 * business data. Responses are the existing approved registry mapping (api/admin.js scRequireRegisteredBusiness):
 *   not_registered → 403 business_not_in_tenant; ambiguous → 503 business_registry_ambiguous; unavailable → 503
 *   business_registry_unavailable; unreadable → 503 business_registry_unreadable; invalid_request → 400 invalid bizId.
 * Consumers that already apply the same registry rule themselves after the gate (Core cost history: requireBusinessInTenant;
 * the Daily manual send: the delivery receipt's registry classification) keep requireBizContext, so no registry read is
 * duplicated or answered differently.
 * @param {{headers:unknown}} req
 * @param {{tenantId:string,bizId:string,mode:"read"|"write"}} opts
 * @param {{requireAuth?:Function,requireTenantAccess?:Function,getDb?:Function}} [deps] test seam
 * @returns {Promise<{uid:string,email:string|null,tenantId:string,bizId:string,role:string,db:unknown}>}
 * @throws {{status:number,msg:string}}
 */
export async function requireRegisteredBizContext(req, opts, deps = {}) {
  const ctx = await requireBizContext(req, opts, deps);
  const t = await readRegistryTarget(ctx.db, ctx.tenantId, ctx.bizId);
  if (t.state === "registered") return ctx;
  if (t.state === "not_registered") throw { status: 403, msg: "business_not_in_tenant" };
  if (t.state === "ambiguous") throw { status: 503, msg: "business_registry_ambiguous" };
  if (t.state === "unavailable") throw { status: 503, msg: "business_registry_unavailable" };
  if (t.state === "invalid_request") throw { status: 400, msg: "invalid bizId" };
  throw { status: 503, msg: "business_registry_unreadable" };
}
